const pools = constants.pools[input.chain];
const pairs = {
  USDC: [['USDC/USDT', pools.USDC_USDT_0_01_pct], ['USDC/DAI', pools.USDC_DAI_0_01_pct]],
  USDT: [['USDC/USDT', pools.USDC_USDT_0_01_pct], ['USDT/DAI', pools.USDT_DAI_0_05_pct]],
  DAI:  [['USDC/DAI', pools.USDC_DAI_0_01_pct], ['USDT/DAI', pools.USDT_DAI_0_05_pct]],
}[input.stablecoin];
return { stablecoin: input.stablecoin, chain: input.chain, pairs };

const Q96 = 2n ** 96n;
const entries = input.pairs.map((pair, i) => {
  const slot = input.slot0_results[i];
  if (!slot) return null;
  const sp = BigInt(slot.sqrtPriceX96);
  const num = (sp * sp);
  const denom = Q96 * Q96;
  // Stablecoins in this set are 6 (USDC/USDT) and 18 (DAI). Decimal alignment
  // is applied by the caller's pool table; here we approximate price as token1/token0.
  const ratio = Number(num * 10000n / denom) / 10000; // float price
  return { pair: pair[0], pool: pair[1], priceUsd: ratio };
}).filter(Boolean);
return { ...input, prices: entries };

const xs = input.prices.map((p) => p.priceUsd).sort((a, b) => a - b);
const median = xs.length === 0 ? null : xs.length % 2 === 0 ? (xs[xs.length/2 - 1] + xs[xs.length/2]) / 2 : xs[(xs.length - 1)/2];
const maxDev = xs.length < 2 ? 0 : (Math.max(...xs) - Math.min(...xs)) / median * 100;
const threshold = 0.5; // 0.5%
const anomaly = maxDev > threshold;
const confidence = xs.length === 0 ? 'low' : maxDev <= 0.1 ? 'high' : maxDev <= 0.5 ? 'medium' : 'low';
return { stablecoin: input.stablecoin, chain: input.chain, prices: input.prices, median, maxDeviationPct: Math.round(maxDev * 100) / 100, confidence, anomaly, anomalyThresholdPct: threshold };
